import {useState} from 'react'
type Item = {id: string; title: string; done: boolean}
export default function App() {
  const [items,setItems] = useState<Item[]>(() => JSON.parse(localStorage.getItem('pa-evaluation-tasks') || '[]'))
  const [title,setTitle] = useState('')
  const [filter,setFilter] = useState('all')
  function save(next: Item[]) { setItems(next); localStorage.setItem('pa-evaluation-tasks',JSON.stringify(next)) }
  const visible = items.filter(item => filter === 'all' || (filter === 'done' ? item.done : !item.done))
  return <main><h1>任务管理</h1>
    <label>任务标题<input value={title} onChange={e=>setTitle(e.target.value)}/></label>
    <button onClick={()=>{if(title.trim()){save([...items,{id:crypto.randomUUID(),title:title.trim(),done:false}]);setTitle('')}}}>添加任务</button>
    <label>状态筛选<select value={filter} onChange={e=>setFilter(e.target.value)}><option value="all">全部</option><option value="open">未完成</option><option value="done">已完成</option></select></label>
    <ul>{visible.map(item=><li key={item.id}><label><input type="checkbox" checked={item.done} onChange={()=>save(items.map(i=>i.id===item.id?{...i,done:!i.done}:i))}/>{item.title}</label><button onClick={()=>save(items.filter(i=>i.id!==item.id))}>删除{item.title}</button></li>)}</ul>
  </main>
}
